-- ===== migrations/0221_zone_counts.sql =====
-- 0221 🗺️ MAP ZONES · counts (owner 2026-11-07; additive, needs 0220). New RPC zone_counts(p_test) for the zoomed-out map:
-- people out tonight per kommun and per län, with the busiest kommun of each län and the busiest bar of each kommun.
-- Privacy:
--   * only counts leave the server, never a position; a pin is put in its kommun on the server (raw lat / lng, 600 m borders);
--   * the same people as the world counter (live, not stopped, ≥ 1 drink) MINUS 👻 spökläge pins and the test zone;
--   * a zone with 1–2 people has no number ("n" missing = "några" in the app); a 👑 line (top kommun / top bar) needs ≥ 3;
--   * zones with nobody are not listed.
-- Cost: built at most once per 60 s for everyone (olnu_zone_cache; one builder at a time, the others take the last row).
-- anon may call it (read-only map view without an account, CONTRACT "SPEED · konto vid första handling").
-- p_test = true only matters for a test user (olnu_is_test_user): the test zone is counted, own cache row, 5 s.

create or replace function public.olnu_kommun_of(p_lat double precision, p_lng double precision)
returns text language sql stable security definer set search_path to 'public' as $$
  -- inside a border; else (SCB's simplified coast: ~7 % of Swedish bars sit just outside, harbours, islands) the nearest
  -- kommun within ~3 km; else null (sea, abroad)
  select coalesce(
    (select z.kn from public.olnu_zone_poly z
      where p_lat is not null and p_lng is not null
        and z.bb @> point(p_lng, p_lat) and z.poly @> point(p_lng, p_lat)
      order by area(z.bb), z.kn
      limit 1),
    (select z.kn from public.olnu_zone_poly z
      where p_lat is not null and p_lng is not null
        and z.bb && box(point(p_lng - 0.06, p_lat - 0.03), point(p_lng + 0.06, p_lat + 0.03))
        and (z.poly <-> point(p_lng, p_lat)) < 0.03
      order by z.poly <-> point(p_lng, p_lat), z.kn
      limit 1));
$$;
revoke all on function public.olnu_kommun_of(double precision, double precision) from public, anon, authenticated;

create table if not exists public.olnu_zone_cache (
  id int primary key,
  at timestamptz not null,
  data jsonb not null
);
alter table public.olnu_zone_cache enable row level security;
revoke all on table public.olnu_zone_cache from public, anon, authenticated;

create or replace function public.olnu_zone_build(p_test boolean)
returns jsonb language plpgsql stable security definer set search_path to 'public' as $$
declare
  k constant int := 3;   -- smallest number shown
  v jsonb;
begin
  with act as (
    select b.lat, b.lng, b.snap_bar
      from public.beers b
     where b.expires_at > now() and not b.stopped and not coalesce(b.ghost, false)
       and (b.beer_count >= 1 or coalesce(b.other_count, 0) >= 1)
       and (p_test or not public.olnu_is_test_zone(b.lat, b.lng))
  ),
  pk as (select public.olnu_kommun_of(a.lat, a.lng) as kn, a.snap_bar from act a),
  kc as (select pk.kn, count(*)::int as n from pk where pk.kn is not null group by pk.kn),
  kb as (
    select distinct on (x.kn) x.kn, x.snap_bar as bar, x.n
      from (select pk.kn, pk.snap_bar, count(*)::int as n from pk where pk.kn is not null and pk.snap_bar is not null group by pk.kn, pk.snap_bar) x
     order by x.kn, x.n desc, x.snap_bar
  ),
  kl as (select kc.kn, kc.n, z.ln from kc join public.olnu_zone_kommun z on z.kn = kc.kn),
  lc as (select kl.ln, sum(kl.n)::int as n from kl group by kl.ln),
  lt as (select distinct on (kl.ln) kl.ln, kl.kn, kl.n from kl order by kl.ln, kl.n desc, kl.kn)
  select jsonb_build_object(
    'v', 1, 'at', now(), 'k', k,
    'total', (select case when sum(kc.n) >= k then sum(kc.n)::int end from kc),
    'some', (select count(*) > 0 from kc),
    'kommun', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                 'c', kc.kn,
                 'n', case when kc.n >= k then kc.n end,
                 'bar', case when kb.n >= k then kb.bar end)) order by kc.kn)
               from kc left join kb on kb.kn = kc.kn), '[]'::jsonb),
    'lan', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                 'c', lc.ln,
                 'n', case when lc.n >= k then lc.n end,
                 'top', case when lt.n >= k then lt.kn end)) order by lc.ln)
               from lc join lt on lt.ln = lc.ln), '[]'::jsonb))
    into v;
  return v;
end;
$$;
revoke all on function public.olnu_zone_build(boolean) from public, anon, authenticated;

create or replace function public.zone_counts(p_test boolean default false)
returns json language plpgsql volatile security definer set search_path to 'public' as $$
declare
  v_test boolean := coalesce(p_test, false) and public.olnu_is_test_user(auth.uid());
  v_id int := case when v_test then 2 else 1 end;
  v_ttl interval := case when v_test then interval '5 seconds' else interval '60 seconds' end;
  v jsonb;
begin
  select c.data into v from public.olnu_zone_cache c where c.id = v_id and c.at > now() - v_ttl;
  if v is not null then return v::json; end if;
  if not pg_try_advisory_xact_lock(873221, v_id) then   -- someone is building it right now: take the last one
    select c.data into v from public.olnu_zone_cache c where c.id = v_id;
    if v is not null then return v::json; end if;
  end if;
  v := public.olnu_zone_build(v_test);
  insert into public.olnu_zone_cache (id, at, data) values (v_id, now(), v)
  on conflict (id) do update set at = excluded.at, data = excluded.data;
  return v::json;
end;
$$;
revoke all on function public.zone_counts(boolean) from public;
grant execute on function public.zone_counts(boolean) to anon, authenticated;


-- ===== migrations/0222_poll_public.sql =====
-- 0222 ⚡ SPEED · konto vid första handling (owner 2026-11-07; additive, no existing function changed).
-- A first visit no longer makes an anonymous account on page open (empty accounts). Until the first real action
-- (🍺 ÖL!, check-in, join a group, open an invite …) the app has NO session and reads the map with this RPC instead of
-- poll_v2. It is exactly the stranger view of poll_v2: the same olnu_pins() rows for p_uid = null (snapped to the bar or the
-- 550 m grid, hashed ids that change every 10 min, created_at in 15 min steps), stranger check-ins (no names), the same
-- k-anonymous heat, live_total without the test zone. No "me", no friends, no rallies, no names. anon + authenticated.

create or replace function public.poll_public(p_min_lat double precision, p_min_lng double precision, p_max_lat double precision,
  p_max_lng double precision, p_heat boolean default false)
returns json language plpgsql stable security definer set search_path to 'public' as $$
declare
  v_cap  constant int := 1500;
  v_a float8; v_b float8; v_c float8; v_d float8;
  v_clat float8; v_clng float8; v_cos float8; v_mlat float8; v_mlng float8;
  v_pins json; v_n_str int;
begin
  if p_min_lat is null or p_min_lng is null or p_max_lat is null or p_max_lng is null
     or 'NaN'::float8 in (p_min_lat, p_min_lng, p_max_lat, p_max_lng)
     or abs(p_min_lat) = 'Infinity'::float8 or abs(p_max_lat) = 'Infinity'::float8
     or abs(p_min_lng) = 'Infinity'::float8 or abs(p_max_lng) = 'Infinity'::float8 then
    raise exception 'invalid_bbox';
  end if;
  -- same box rules as poll_v2 (date line, 15 % margin, clamp)
  v_a := least(p_min_lat, p_max_lat);  v_c := greatest(p_min_lat, p_max_lat);
  v_b := least(p_min_lng, p_max_lng);  v_d := greatest(p_min_lng, p_max_lng);
  if p_min_lng > p_max_lng and p_min_lng <= 180 and p_max_lng >= -180 then v_b := -180; v_d := 180; end if;
  v_mlat := greatest((v_c - v_a) * 0.15, 0.005);
  v_mlng := greatest((v_d - v_b) * 0.15, 0.01);
  v_a := greatest(-85.0, v_a - v_mlat);  v_c := least(85.0, v_c + v_mlat);
  v_b := v_b - v_mlng;  v_d := v_d + v_mlng;
  if v_b < -180 or v_d > 180 then v_b := -180; v_d := 180; end if;
  if v_a > v_c or v_b > v_d then v_a := 0; v_c := 0; v_b := 0; v_d := 0; end if;
  v_clat := (v_a + v_c) / 2;  v_clng := (v_b + v_d) / 2;  v_cos := cos(radians(v_clat));

  with p as (select * from public.olnu_pins(null::uuid, v_a, v_b, v_c, v_d)),
  ranked as (
    select p.*, row_number() over (order by power(p.lat - v_clat, 2) + power((p.lng - v_clng) * v_cos, 2), p.pin_id) as rn,
           count(*) over () as nstr
      from p
  ),
  sel as (select * from ranked r where r.rn <= v_cap),
  sk as (select s.beer_id as sid, count(*)::int as n from public.skals s join sel on sel.beer_id = s.beer_id group by s.beer_id),
  rx1 as (select r.beer_id as rid, r.emoji, count(*)::int as n from public.reactions r join sel on sel.beer_id = r.beer_id where r.active group by r.beer_id, r.emoji),
  rx as (select rx1.rid, jsonb_object_agg(rx1.emoji, rx1.n) as counts from rx1 group by rx1.rid)
  select coalesce(json_agg(json_strip_nulls(json_build_object(
           'id', sel.pin_id, 'lat', sel.lat, 'lng', sel.lng, 'snap', sel.snap, 'bar_id', sel.bar_id, 'precise', sel.precise,
           'beer_count', sel.beer_count, 'other_count', nullif(sel.other_count, 0),
           'other_kind', case when sel.other_count > 0 then sel.other_kind end,
           'created_at', sel.created_at, 'skal_count', sk.n, 'rx', rx.counts
         )) order by sel.created_at, sel.pin_id), '[]'::json),
         coalesce(max(sel.nstr), 0)
    into v_pins, v_n_str
    from sel left join sk on sk.sid = sel.beer_id left join rx on rx.rid = sel.beer_id;

  return json_build_object(
    'v', 1, 'public', true, 'server_time', now(), 'full', true,
    'bbox', json_build_array(v_a, v_b, v_c, v_d),
    'pins', v_pins, 'capped', v_n_str > v_cap, 'pins_in_view', v_n_str,
    'live_total', (select count(*)::int from public.beers b
                    where b.expires_at > now() and not b.stopped
                      and (b.beer_count >= 1 or coalesce(b.other_count, 0) >= 1)
                      and not public.olnu_is_test_zone(b.lat, b.lng)),
    'me', null,
    'checkins', (select coalesce(json_agg(json_build_object(
                    'bar_id', c.bar_id, 'bar_name', c.bar_name, 'lat', c.lat, 'lng', c.lng, 'name', null,
                    'is_mine', false, 'is_friend', false,
                    'created_at', to_timestamp(floor(extract(epoch from c.created_at) / 900) * 900)
                  ) order by c.created_at), '[]'::json)
                   from (select * from public.checkins c0
                          where c0.expires_at > now() and not public.olnu_is_test_zone(c0.lat, c0.lng)
                            and c0.lat between v_a and v_c and c0.lng between v_b and v_d
                          order by c0.created_at limit 2000) c),
    'rallies', '[]'::json,
    'heat', case when coalesce(p_heat, false) then
              (select coalesce(json_agg(json_build_array(h.lat, h.lng, h.w)), '[]'::json)
                 from public.olnu_heat(v_a - (v_c - v_a) * 0.5, v_b - (v_d - v_b) * 0.5,
                                       v_c + (v_c - v_a) * 0.5, v_d + (v_d - v_b) * 0.5, 3000) h)
            end
  );
end;
$$;
revoke all on function public.poll_public(double precision, double precision, double precision, double precision, boolean) from public;
grant execute on function public.poll_public(double precision, double precision, double precision, double precision, boolean) to anon, authenticated;


-- ===== migrations/0223_test_users.sql =====
-- 0223 🧪 TEST USERS (owner 2026-11-07; additive, owner_stats itself is NOT changed).
-- The test scripts tag their own fresh anonymous users, and the owner page counts real people only.
-- A user is a test user when ANY of:
--   * auth user_metadata {"test": true}  (scripts: client.auth.updateUser({ data: { test: true } }) right after signInAnonymously)
--   * a row in olnu_test_users            (scripts: rpc("mark_me_test") — same effect, for clients that cannot set metadata)
--   * the old rule olnu_is_test_user()    (a pin / check-in / push location in the test zone, lat 68.25–68.45, lng 18.60–19.00)
-- user_metadata is writable by the user: a person can only hide HIMSELF from the owner's counts, nothing else changes for him.
-- owner_stats2(p_key) = owner_stats(p_key) with the "users" block counted without test users, plus users.test_users.
-- stats.html asks owner_stats2 first and falls back to owner_stats (old server).

create table if not exists public.olnu_test_users (
  user_id uuid primary key,
  created_at timestamptz not null default now()
);
alter table public.olnu_test_users enable row level security;
revoke all on table public.olnu_test_users from public, anon, authenticated;

create or replace function public.olnu_is_test_uid(p_uid uuid)
returns boolean language sql stable security definer set search_path to 'public' as $$
  select p_uid is not null and (
    exists (select 1 from auth.users u where u.id = p_uid and coalesce(u.raw_user_meta_data ->> 'test', '') in ('true', '1'))
    or exists (select 1 from public.olnu_test_users t where t.user_id = p_uid)
    or public.olnu_is_test_user(p_uid));
$$;
revoke all on function public.olnu_is_test_uid(uuid) from public, anon, authenticated;

create or replace function public.mark_me_test()
returns json language plpgsql volatile security definer set search_path to 'public' as $$
declare v uuid := public.olnu_uid();
begin
  insert into public.olnu_test_users (user_id) values (v) on conflict do nothing;
  return json_build_object('ok', true);
end;
$$;
revoke all on function public.mark_me_test() from public, anon;
grant execute on function public.mark_me_test() to authenticated;

create or replace function public.owner_stats2(p_key text)
returns jsonb language plpgsql volatile security definer set search_path to 'public' as $$
declare
  v       jsonb := public.owner_stats(p_key);   -- does the key check, rate limit and fail log
  v_now   timestamptz := now();
  v_next  timestamptz := public.olnu_next_expiry();
  v_today timestamptz := date_trunc('day', now() at time zone 'Europe/Stockholm') at time zone 'Europe/Stockholm';
  v_users jsonb;
begin
  if v is null or v ? 'code' or not (v ? 'users') then return v; end if;   -- forbidden / rate limited
  create temporary table if not exists olnu_tmp_real on commit drop as
    select u.id, u.created_at from auth.users u where not public.olnu_is_test_uid(u.id);
  v_users := (v -> 'users') || jsonb_build_object(
    'total', (select count(*) from olnu_tmp_real),
    'named', (select count(distinct g.user_id) from public.group_members g join olnu_tmp_real r on r.id = g.user_id),
    'new_today', (select count(*) from olnu_tmp_real where created_at >= v_today),
    'new_7d', (select count(*) from olnu_tmp_real where created_at > v_now - interval '7 days'),
    'new_30d', (select count(*) from olnu_tmp_real where created_at > v_now - interval '30 days'),
    'active_tonight', (select count(distinct a.uid) from (
        select b.user_id uid from public.beers b
         where b.expires_at = v_next and (coalesce(b.beer_count, 0) + coalesce(b.other_count, 0) + coalesce(b.shot_count, 0)) > 0
        union all
        select c.user_id from public.checkins c where c.expires_at = v_next) a join olnu_tmp_real r on r.id = a.uid),
    'out_now', (select count(*) from public.beers b join olnu_tmp_real r on r.id = b.user_id
                 where b.expires_at > v_now and not coalesce(b.stopped, false)),
    'opened_7d', (select count(distinct s.user_id) from auth.sessions s join olnu_tmp_real r on r.id = s.user_id
                   where s.updated_at > v_now - interval '7 days'),
    'push', (select count(distinct p.user_id) from public.push_subscriptions p join olnu_tmp_real r on r.id = p.user_id),
    'test_users', (select count(*) from auth.users) - (select count(*) from olnu_tmp_real),
    'empty_anon', (select count(*) from olnu_tmp_real r
                    where not exists (select 1 from public.group_members g where g.user_id = r.id)
                      and not exists (select 1 from public.beers b where b.user_id = r.id)
                      and not exists (select 1 from public.checkins c where c.user_id = r.id)),
    'real_only', true);
  return jsonb_set(v, '{users}', v_users);
end;
$$;
revoke all on function public.owner_stats2(text) from public;
grant execute on function public.owner_stats2(text) to anon, authenticated;


-- ===== migrations/0224_rpc_deprecated_notes.sql =====
-- 0224 🧹 RPCs with no caller in the repo (owner 2026-11-07; comments only — NOTHING is dropped or changed).
-- Old clients may still call them (compatibility rule). Drop only after 30 days with 0 calls (pg_stat_statements).
-- Re-checked 2026-11-07 against docs/, supabase/functions/, scripts/ and .github/ (word match): the code review list of 14 was
-- stale — spel_act/group/mine/open/state, event_group, event_story, my_night_log and my_past_events ARE used again.
-- Still unused from that list: find_cancel, group_rallies, like_msg, msg_likes, my_eta (marked below).
-- Other functions with EXECUTE for anon/authenticated and no caller in this branch (NOT marked: the store-safe / trust work
-- and the owner tools may add their callers): accept_terms, bar_norm, block_user, unblock_user, my_blocks, ikvall_set,
-- ikvall_status, owner_feedback, owner_set_feedback, owner_mask_test, owner_move_stats, owner_report_act, owner_report_photo,
-- owner_reports, report_content, safety_state, set_age_ok, submit_feedback.

do $$
declare r record;
begin
  for r in select p.oid::regprocedure as f from pg_proc p join pg_namespace n on n.oid = p.pronamespace
            where n.nspname = 'public' and p.proname in ('find_cancel', 'group_rallies', 'like_msg', 'msg_likes', 'my_eta') loop
    execute format('comment on function %s is %L', r.f,
      'DEPRECATED 2026-11-07: no caller in the app any more (old clients only). Drop after 30 days with 0 calls.');
  end loop;
end;
$$;

select 'KLART - allt kördes' as status;
